export const FAMILY_BY_ID = Object.fromEntries(CAREER_FAMILIES.map((f) => [f.id, f]));

/* --------------------------------------------------------------- scoring */

/** Turn raw scenario answers into a normalised trait profile. */
export function scoreAnswers(answers = []) {
  const tally = new Map();
  const answered = [];
  for (const a of answers) {
    const scenario = SCENARIO_BY_ID[a.scenarioId];
    if (!scenario) continue;
    const option = scenario.options.find((o) => o.id === a.optionId);
    if (!option) continue;
    answered.push({ scenarioId: scenario.id, dimension: scenario.dimension, optionId: option.id });
    for (const [tag, weight] of Object.entries(option.tags || {})) {
      tally.set(tag, (tally.get(tag) || 0) + weight);
    }
  }
  const total = [...tally.values()].reduce((a, b) => a + b, 0) || 1;
  const traits = [...tally.entries()]
    .map(([id, score]) => ({
      id,
      label: TRAIT_LABELS[id] || id,
      score: Math.round((score / total) * 1000) / 10,
      raw: score,
    }))
    .sort((a, b) => b.raw - a.raw || a.id.localeCompare(b.id));
  return { traits, answered, answeredCount: answered.length, maxScore: total };
}

/** Rank career families against the trait profile. */
export function rankFamilies(profile, limit = 5) {
  const traitScore = new Map(profile.traits.map((t) => [t.id, t.score]));
  const maxRaw = profile.traits[0]?.raw || 1;
  const scored = CAREER_FAMILIES.map((family) => {
    const matched = family.traits
      .map((t) => ({ trait: t, value: traitScore.get(t) || 0 }))
      .sort((a, b) => b.value - a.value);
    const familyRaw = matched.reduce((sum, m) => sum + m.value, 0);
    const fit = Math.round((familyRaw / (maxRaw * family.traits.length)) * 1000) / 10;
    const reasons = matched
      .filter((m) => m.value > 0)
      .slice(0, 3)
      .map((m) => `${m.trait}`);
    return {
      id: family.id,
      label: family.label,
      description: family.description,
      soc: family.soc,
      fit,
      confidence: Math.min(95, Math.round(40 + fit * 0.6)),
      matchReasons: reasons,
    };
  });
  return scored.sort((a, b) => b.fit - a.fit || a.id.localeCompare(b.id)).slice(0, limit);
}

/* --------------------------------------------------- Career DNA profile */

export function buildCareerDna(answers) {
  const profile = scoreAnswers(answers);
  const families = rankFamilies(profile);
  const primary = families[0];
  const secondary = families[1];
  const workingStyle =
    profile.traits.some((t) => t.id === 'focus' && t.score > 6)
      ? 'Deep-focus individual contributor with structured deliverables'
      : profile.traits.some((t) => t.id === 'social' && t.score > 6)
        ? 'Collaborative generalist who thrives in mixed group work'
        : 'Adaptive problem-solver who moves between focused and social modes';

  return {
    id: uid('dna_'),
    generatedAt: nowIso(),
    mode: 'demo',
    traitProfile: profile.traits,
    answeredCount: profile.answeredCount,
    primaryFamily: primary,
    secondaryFamily: secondary,
    workingStyle,
    strengths: profile.traits.slice(0, 5).map((t) => ({
      trait: t.label,
      score: t.score,
      evidence: `Derived from ${profile.answeredCount} scenario responses`,
    })),
    watchOuts: profile.traits.slice(-3).map((t) => ({
      trait: t.label,
      score: t.score,
      note: 'Lower signal in your answers — worth stress-testing in a real task.',
    })),
    summary: `Your answers point most strongly to ${primary?.label || 'a mixed profile'}, with ${secondary?.label || 'a secondary path'} as a credible alternative. This summary comes from the offline rules engine; connect an AI provider for a richer narrative.`,
  };
}

/* --------------------------------------------------- 2. Hidden careers */

export function hiddenCareers(profile) {
  const families = rankFamilies(profile, 6);
  const p = profile.primaryFamily;
  return {
    id: uid('hc_'),
    generatedAt: nowIso(),
    mode: 'demo',
    explanation:
      'Careers are surfaced from your behavioural traits, not from job titles you selected. Each card shows which of your answers pushed it up.',
    cards: families.map((f) => ({
      id: f.id,
      title: f.label,
      family: f.label,
      socCodes: f.soc,
      fit: f.fit,
      confidence: f.confidence,
      why: `Your strongest signals were ${f.matchReasons.join(', ') || 'general adaptability'}.`,
      hiddenBecause:
        f.id === p?.id
          ? 'You did not mention this field at all, yet your answers line up with it.'
          : 'Adjacent to fields you already know, but built on a different kind of work.',
      suggestedFirstStep: `Search for entry-level ${f.label.toLowerCase()} roles and read three job descriptions.`,
    })),
  };
}

/* -------------------------------------------- 3. Talent Evidence Lab */

export function talentEvidence(profile, priorEvidence = []) {
  const families = rankFamilies(profile, 3);
  const samples = [];
  for (const f of families) {
    samples.push({
      id: uid('ev_'),
      family: f.label,
      socCodes: f.soc,
      task: `Complete a short, real brief in ${f.label.toLowerCase()} and record what you did.`,
      proof:
        f.id === 'analyse'
          ? 'A one-page analysis with your source list and one recommendation.'
          : f.id === 'people'
            ? 'A recorded walkthrough of how you explained a decision to someone.'
            : f.id === 'create'
              ? 'A published artefact plus a note on the choices you made.'
              : 'A working artefact plus a short README describing your decisions.',
      verification: 'verified' in f ? 'self_reported' : 'self_reported',
      status: 'suggested',
    });
  }
  return {
    id: uid('te_'),
    generatedAt: nowIso(),
    mode: 'demo',
    note:
      'Evidence Lab proposes tasks that surface your strongest traits. Nothing here is verified until you attach a link or file.',
    samples,
    existing: priorEvidence,
  };
}

/* -------------------------------------------- 4. Experience Translator */

const TASK_VERBS = ['Led', 'Built', 'Improved', 'Designed', 'Analysed', 'Coordinated', 'Automated', 'Resolved'];

export function translateExperience(text) {
  const words = keywords(text, 25);
  const sentences = String(text)
    .split(/(?<=[.!?])\s+/)
    .map((s) => s.trim())
    .filter(Boolean);
  const bullets = sentences.slice(0, 6).map((s) => {
    const verb = TASK_VERBS.find((v) => s.toLowerCase().includes(v.toLowerCase())) || 'Delivered';
    const cleaned = s.replace(/^[Ii]\s+/, '').replace(/\s+/g, ' ').trim();
    return cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
  });
  const skillHints = words.filter((w) =>
    ['data', 'reports', 'spreadsheet', 'excel', 'sql', 'python', 'customer', 'sales', 'team', 'budget', 'process', 'research', 'design', 'code'].includes(w),
  );
  return {
    id: uid('ex_'),
    generatedAt: nowIso(),
    mode: 'demo',
    original: String(text).slice(0, 4000),
    bullets,
    keywords: words,
    transferable: skillHints.length
      ? skillHints.map((s) => ({
          skill: s,
          howItTransfers: `Your experience with ${s} maps onto roles that rely on it daily.`,
        }))
      : [
          {
            skill: 'Communication',
            howItTransfers: 'Explaining your work clearly transfers into almost every client-facing and team role.',
          },
        ],
    note: 'Generated by the offline rules engine — review and rewrite in your own voice.',
  };
}

